//! 🧪️ Native causal clone custody preserves original shared actor leases and complete portable value output.
use super::*;
use semio_framework_value::{FromValue,ToValue,RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,RetirementDemand,OriginalRetirementFailure,ValueError,retained_clone::{RetainedClone,RetainedCloneCursor,RetainedCloneStep},retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_clone_source_testing::{FixtureSource,FixtureSourceBirth,FixtureCloseStep,drive};
const WORK:u64=1<<20;
const BODY:usize=4096;
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes+d.capacity_bytes<=4096,"native envelope clone indivisible body {:?}",d);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
fn stage<T:Sync+'static+RetireOwned>(value:T)->FixtureSource<T>{<RetainedCloneSource<T> as FixtureSourceBirth<T>>::from_owner(value)}
fn heap(progress:RetainedCloneProgress)->(usize,usize){(progress.retained_capacity_bytes,progress.released_bytes)}
/// 🚗️ Runs one controlled retirement turn under a real original Work action; the action itself proves the heap equals the receipt.
pub(crate) fn stepped<T:RetireOwned>(owner:&mut ControlledRetirement<T>,grant:RetainedCloneGrant)->(RetainedCloneStep,(usize,usize)){drive::warm();let step=drive::drive(grant,WORK,|effect|owner.step(grant.maximum_copy_bytes,effect)).result.expect("original controlled step");let receipt=step.progress();(step,heap(receipt))}
fn advanced(cursor:&mut impl RetainedCloneCursor<MutationEnvelope>,source:&FixtureSource<MutationEnvelope>,grant:RetainedCloneGrant)->semio_framework_value::RetainedWorkOutcome<RetainedCloneStep,OriginalRetirementFailure>{drive::warm();drive::drive_reply::<RetainedCloneStep,OriginalRetirementFailure>(grant,WORK,|reply|match reply{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()},|effect,reply,recover|if recover{cursor.recover_advance_into(source.borrow(),BODY,WORK,effect,reply)}else{cursor.advance_into(source.borrow(),BODY,WORK,effect,reply)})}
fn taken(cursor:&mut impl RetainedCloneCursor<MutationEnvelope>,grant:RetainedCloneGrant)->(semio_framework_value::RetainedWorkOutcome<RetainedCloneStep,ValueError>,Option<MutationEnvelope>){let mut output=None;drive::warm();let outcome=drive::drive_reply::<RetainedCloneStep,ValueError>(grant,WORK,|reply|match reply{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()},|effect,reply,recover|if recover{cursor.recover_take(&mut output,effect,reply)}else{cursor.take(&mut output,effect,reply)});(outcome,output)}
fn began(cursor:&mut impl RetainedCloneCursor<MutationEnvelope>){let admitted=grant(cursor.begin_close_demand().unwrap());drive::warm();drive::drive_reply::<RetainedCloneStep,OriginalRetirementFailure>(admitted,WORK,|reply|match reply{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()},|effect,reply,recover|if recover{cursor.recover_begin_close_into(effect,reply)}else{cursor.begin_close_into(effect,reply)}).result.unwrap();}
fn closed(cursor:&mut impl RetainedCloneCursor<MutationEnvelope>,grant:RetainedCloneGrant)->(RetainedCloneStep,(usize,usize)){drive::warm();let step=drive::drive_reply::<RetainedCloneStep,OriginalRetirementFailure>(grant,WORK,|reply|match reply{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()},|effect,reply,recover|if recover{cursor.recover_close_into(BODY,effect,reply)}else{cursor.close_into(BODY,effect,reply)}).result.unwrap();let receipt=step.progress();(step,heap(receipt))}
fn drained(source:&mut FixtureSource<MutationEnvelope>){for turn in 0..32768{if source.terminal_is_empty(){break}let admitted=grant(source.next_close_demand(BODY).unwrap());match source.close_with(BODY,admitted).unwrap(){FixtureCloseStep::Progress(progress)=>assert!(progress.fits(admitted)),FixtureCloseStep::Pending|FixtureCloseStep::Complete=>{},denied=>panic!("source close was not funded: {denied:?}")}assert!(turn<32767);}assert!(source.terminal_is_empty());}
fn close<T:RetireOwned>(value:T){let mut owner=ControlledRetirement::new(value).ok().unwrap();for turn in 0..32768{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();let(step,spent)=stepped(&mut owner,grant(d));assert_eq!(spent,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(turn<32767)}}
#[test]
fn original_causal_envelope_clone_preserves_wire_value_and_shared_actor_identity(){let expected:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for prefix in [0,1,2,7,29,usize::MAX]{let original=MutationEnvelope::from_value(expected.clone().into()).unwrap();let actor=original.actor.0.as_str().as_ptr();type Source=RetainedCloneSource<MutationEnvelope>;let mut source=stage(original);let foreign=MutationEnvelope::from_value(expected.clone().into()).unwrap();let mut foreign=stage(foreign);let mut cursor=MutationEnvelope::retained_clone_cursor();let mut steps=0;while !cursor.output_ready()&&steps<prefix{let d=cursor.advance_demands(source.borrow(),BODY,WORK).unwrap();for axis in 0..5{let value=match axis{0=>1,1=>d.copy_bytes,2=>d.capacity_bytes,3=>d.release_bytes,_=>d.depth};if value==0{continue}let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1};let step=advanced(&mut cursor,&source,denied).result.unwrap();assert_eq!(step.progress(),RetainedCloneProgress::default());assert_eq!(heap(step.progress()),(0,0));}advanced(&mut cursor,&source,grant(d)).result.unwrap();steps+=1;if steps>1{let error=advanced(&mut cursor,&foreign,grant(d)).result.unwrap_err();assert_eq!(error.retained_progress(),Default::default());}assert!(steps<32768);}let output=if prefix==usize::MAX{{let admitted=grant(cursor.take_demand().unwrap());let(outcome,output)=taken(&mut cursor,admitted);outcome.result.unwrap();Some(output.unwrap())}}else{None};if let Some(output)=output.as_ref(){assert_eq!(serde_json::Value::from(output.to_value()),expected);assert_eq!(output.actor.0.as_str().as_ptr(),actor);}began(&mut cursor);for turn in 0..32768{if cursor.terminal_is_empty(){break}let d=cursor.close_demands(BODY).unwrap();let(step,spent)=closed(&mut cursor,grant(d));assert_eq!(spent,heap(step.progress()));assert!(turn<32767);}assert!(cursor.terminal_is_empty());if let Some(output)=output{close(output)}for source in [&mut source,&mut foreign]{drained(source);}}}
